// Parse streaming output
const output = $input.first().json.stdout;
const lines = output.split('\n');

let response = '';
let sources = [];
let confidence = 0.0;
let conversationId = '';

for (const line of lines) {
  try {
    const data = JSON.parse(line);
    if (data.type === 'response') response = data.content;
    if (data.type === 'sources') sources = data.content;
    if (data.type === 'confidence') confidence = data.content;
    if (data.type === 'complete') conversationId = data.conversationId;
  } catch (e) {
    // Skip invalid JSON lines
  }
}

return {
  json: {
    response: response,
    sources: sources,
    confidence: confidence,
    conversationId: conversationId
  }
};
